#!/usr/bin/env bash\n# nightly-uptime-emoji-reporter\n# Reads load average and prints uptime with an emoji.\n\n# Function to obtain the first load‑average value.\nget_load() {\n  if [[ -n "$MOCK_LOAD" ]]; then\n    echo "$MOCK_LOAD"\n  else\n    awk '{print $1}' /proc/loadavg\n  fi\n}\n\n# Function to obtain a human‑readable uptime string.\nget_uptime() {\n  if [[ -n "$MOCK_UPTIME" ]]; then\n    echo "$MOCK_UPTIME"\n  else\n    if uptime -p >/dev/null 2>&1; then\n      uptime -p | sed 's/^up //'\n    else\n      secs=$(awk '{print int($1)}' /proc/uptime)\n      days=$((secs/86400))\n      hrs=$(((secs%86400)/3600))\n      mins=$(((secs%3600)/60))\n      out=""\n      [[ $days -gt 0 ]] && out="${out}${days}d "\n      [[ $hrs -gt 0 ]] && out="${out}${hrs}h "\n      [[ $mins -gt 0 ]] && out="${out}${mins}m"\n      echo "$out"\n    fi\n  fi\n}\n\n# Determine emoji based on load.\nload=$(get_load)\nif (( $(echo "$load < 0.5" | bc -l) )); then\n  emoji="🌞"\nelif (( $(echo "$load < 2.0" | bc -l) )); then\n  emoji="😐"\nelse\n  emoji="😱"\nfi\n\nuptime_str=$(get_uptime)\necho "Uptime: $uptime_str, Load: $load $emoji"\n
